(function(){
  var t = scope.op_type;
  var k = scope.num;
  var stmt, expr, ans, step1;
  if (t === 0) {
    stmt = 'Add $x$ and $y$';
    ans = 'x + y';
    step1 = 'Addition of $x$ and $y$ gives $x + y$.';
  } else if (t === 1) {
    stmt = 'Subtract $c$ from ' + k;
    ans = k + ' - c';
    step1 = 'Subtracting $c$ from ' + k + ' gives $' + k + ' - c$.';
  } else if (t === 2) {
    stmt = 'Product of ' + k + ' and $d$';
    ans = k + 'd';
    step1 = 'Multiplying ' + k + ' and $d$ gives $' + k + 'd$.';
  } else {
    stmt = 'Divide $a$ by ' + k;
    ans = 'a/' + k;
    step1 = 'Dividing $a$ by ' + k + ' gives $\\frac{a}{' + k + '}$.';
  }
  return { stmt: stmt, ans: ans, step1: step1 };
})()

(function(){
  var t = scope.sit_type;
  var k = scope.k, amt = scope.amt;
  var sit, ans, step;
  if (t === 0) {
    sit = 'Faizal had $c$ books. His friend gives him ' + k + ' books on his birthday. How many books does he have now?';
    ans = 'c + ' + k;
    step = 'Add ' + k + ' to initial amount $c$: $c + ' + k + '$.';
  } else if (t === 1) {
    sit = 'Mei Ling had \\$' + amt + '. She donates \\$y to charity. How much money does she have now?';
    ans = amt + ' - y';
    step = 'Subtract donation $y$ from \\$' + amt + ': $' + amt + ' - y$.';
  } else if (t === 2) {
    sit = 'A box contains $d$ cookies. How many cookies are there in ' + k + ' such boxes?';
    ans = k + 'd';
    step = 'Multiply $d$ by ' + k + ' boxes: $' + k + 'd$.';
  } else {
    sit = 'There are $x$ pears. The pears are shared equally among ' + k + ' persons. How many pears does each person get?';
    ans = 'x/' + k;
    step = 'Divide total pears $x$ by ' + k + ' persons: $\\frac{x}{' + k + '}$.';
  }
  return { sit: sit, ans: ans, step: step };
})()

(function(){
  var i = scope.idx;
  var k = scope.k;
  var cases = [
    { expr: 'x \\times x', ans: 'x^2', step: 'x \\times x = x^2' },
    { expr: 'a \\times a \\times a', ans: 'a^3', step: 'a \\times a \\times a = a^3' },
    { expr: 'b \\times c \\times c', ans: 'bc^2', step: 'b \\times (c \\times c) = bc^2' },
    { expr: k + ' \\times x^2', ans: k + 'x^2', step: k + ' \\times x^2 = ' + k + 'x^2' },
    { expr: k + ' \\times y^3', ans: k + 'y^3', step: k + ' \\times y^3 = ' + k + 'y^3' },
    { expr: k + ' \\times a \\times b^2', ans: k + 'ab^2', step: k + ' \\times a \\times b^2 = ' + k + 'ab^2' }
  ];
  var item = cases[i % cases.length];
  return { expr: item.expr, ans: item.ans, step: item.step };
})()

(function(){
  var i = scope.idx;
  var k = scope.k;
  var cases = [
    { expr: '(a + b) \\times ' + k, ans: k + '(a + b)', step: '(a + b) \\times ' + k + ' = ' + k + '(a + b)' },
    { expr: '(x + y) \\times \\frac{1}{' + k + '}', ans: '(x + y)/' + k, step: '(x + y) \\times \\frac{1}{' + k + '} = \\frac{x + y}{' + k + '}' },
    { expr: '(a + x) \\div ' + k, ans: '(a + x)/' + k, step: '(a + x) \\div ' + k + ' = \\frac{a + x}{' + k + '}' }
  ];
  var item = cases[i % cases.length];
  return { expr: item.expr, ans: item.ans, step: item.step };
})()

(function(){
  var t = scope.sit_type;
  var k = scope.k, m = scope.m;
  var sit, ans, step;
  if (t === 0) {
    sit = 'A container contains $a$ pencils from Brand A and $b$ pencils from Brand B. How many pencils are there in ' + k + ' such containers?';
    ans = k + '(a + b)';
    step = 'First find pencils in 1 container: $a + b$. Then multiply by ' + k + ': $' + k + '(a + b)$.';
  } else if (t === 1) {
    sit = 'A box contains $x$ cups. Mary has ' + k + ' such boxes. She gives her friend ' + m + ' cups. How many cups does she have now?';
    ans = k + 'x - ' + m;
    step = 'Total in ' + k + ' boxes is $' + k + 'x$. Subtract ' + m + ' given away: $' + k + 'x - ' + m + '$.';
  } else if (t === 2) {
    sit = 'Francis had \\$x. He spends \\$y. He then distributes the remaining amount of money equally among ' + k + ' charities. How much money does each charity receive?';
    ans = '(x - y)/' + k;
    step = 'Remaining amount is $x - y$. Divide equally by ' + k + ': $\\frac{x - y}{' + k + '}$.';
  } else {
    sit = 'There are $a$ pens and $b$ erasers. The pens and erasers are divided equally between ' + k + ' persons. How many pens and erasers will each person get?';
    ans = '(a + b)/' + k;
    step = 'Total items = $a + b$. Divide equally by ' + k + ': $\\frac{a + b}{' + k + '}$.';
  }
  return { sit: sit, ans: ans, step: step };
})()
